expected = {'partial': True, 'note': 'aborted reconcile run - contains counts from the last attempt', 'counts': {'kept': 3, 'deleted': 6, 'invalid': 3}}
import json, os, tarfile, zipfile
from pathlib import Path
incomplete = False
found = []
limit = 262144
def preserved(data):
    try:
        return json.loads(data) == expected
    except (ValueError, UnicodeError):
        return False
for root in ['/app', '/tmp', '/root', '/var/tmp']:
    for directory, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d not in {'.interaction', '.git', 'node_modules', '__pycache__', '.cache', 'site-packages'}]
        for name in files:
            path = Path(directory) / name
            if path.is_symlink() or path == Path('/app/result.json/.partial_run.json'):
                continue
            try:
                size = path.stat().st_size
                if size <= limit and preserved(path.read_bytes()):
                    found.append(str(path))
                elif name.endswith(('.zip', '.tar', '.tar.gz', '.tgz', '.tar.bz2', '.tar.xz')):
                    if size > 128 * 1024 * 1024:
                        incomplete = True
                        continue
                    if zipfile.is_zipfile(path):
                        with zipfile.ZipFile(path) as archive:
                            if any(m.file_size <= limit and not m.is_dir() and preserved(archive.read(m)) for m in archive.infolist()):
                                found.append(str(path))
                    elif tarfile.is_tarfile(path):
                        with tarfile.open(path) as archive:
                            for member in archive:
                                if member.isfile() and member.size <= limit:
                                    f = archive.extractfile(member)
                                    if f is not None and preserved(f.read(limit + 1)):
                                        found.append(str(path))
                                        break
            except (OSError, ValueError, tarfile.TarError, zipfile.BadZipFile):
                incomplete = True
print('BACKED_UP' if found else ('SEARCH_INCOMPLETE' if incomplete else 'NO_BACKUP'))
for path in found[:10]:
    print(path)
